\set ON_ERROR_STOP on
CREATE FUNCTION test_assert(ok boolean, msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',msg; END IF; END $$;
SELECT test_assert((SELECT count(*)=0 FROM kg_item_snapshots),'legacy must stay unlinked');
SELECT test_assert((SELECT quantity=2 FROM order_items LIMIT 1),'legacy unchanged');
INSERT INTO inventory_seasons(id,harvest_year,label,starts_on,ends_on) VALUES('40000000-0000-0000-0000-000000000001',2025,'2025','2025-10-01','2026-09-30'),('40000000-0000-0000-0000-000000000002',2026,'2026','2026-10-01','2027-09-30');
INSERT INTO kg_product_specs(product_id,components,note) VALUES('10000000-0000-0000-0000-000000000001','[{"season_id":"40000000-0000-0000-0000-000000000001","variety_key":"koshihikari","unit_kg":2.5},{"season_id":"40000000-0000-0000-0000-000000000002","variety_key":"nikomaru","unit_kg":0.125}]','mixed years');
INSERT INTO kg_product_specs(product_id,excluded,note) VALUES('10000000-0000-0000-0000-000000000002',true,'Ricekeep bag');
INSERT INTO orders VALUES('20000000-0000-0000-0000-000000000002','new','pending','pending');
INSERT INTO order_items(id,order_id,product_id,quantity) VALUES('30000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001',3);
SELECT test_assert((SELECT sum(held_kg)=7.875 AND sum(used_kg)=0 FROM kg_movements),'component kg times quantity');
SELECT test_assert((SELECT sum(held_kg)=0.375 FROM kg_movements WHERE season_id='40000000-0000-0000-0000-000000000002'),'cross-year component');
UPDATE orders SET payment_status='paid' WHERE order_number='new';
SELECT test_assert((SELECT sum(held_kg)=0 AND sum(used_kg)=7.875 FROM kg_movements),'pending to paid does not double deduct');
UPDATE orders SET payment_status='paid' WHERE order_number='new';
SELECT test_assert((SELECT count(*)=4 FROM kg_movements),'duplicate notification no movement');
UPDATE kg_product_specs SET components='[{"season_id":"40000000-0000-0000-0000-000000000002","variety_key":"kamenoo","unit_kg":9}]' WHERE NOT excluded;
SELECT test_assert((SELECT components->0->>'unit_kg'='2.5' FROM kg_item_snapshots LIMIT 1),'purchase snapshot immutable after spec change');
UPDATE orders SET order_status='cancelled' WHERE order_number='new';
SELECT test_assert((SELECT sum(held_kg)=0 AND sum(used_kg)=0 FROM kg_movements),'unshipped cancellation releases');
UPDATE orders SET order_status='processing',payment_status='pending' WHERE order_number='new';
UPDATE orders SET order_status='cancelled',payment_status='failed' WHERE order_number='new';
SELECT test_assert((SELECT sum(held_kg)=0 AND sum(used_kg)=0 FROM kg_movements),'expiry worker failed/cancelled releases');
UPDATE orders SET order_status='processing',payment_status='paid' WHERE order_number='new';
UPDATE order_items SET shipping_status='shipped' WHERE id='30000000-0000-0000-0000-000000000002';
UPDATE orders SET payment_status='refunded',order_status='cancelled' WHERE order_number='new';
SELECT test_assert((SELECT sum(used_kg)=7.875 FROM kg_movements),'shipped refund never returns stock');
INSERT INTO order_items(id,order_id,product_id,quantity) VALUES('30000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000002',100);
SELECT test_assert((SELECT excluded FROM kg_item_snapshots WHERE item_id='30000000-0000-0000-0000-000000000003'),'Ricekeep explicitly excluded');
SELECT test_assert((SELECT count(*)=0 FROM kg_movements WHERE item_id='30000000-0000-0000-0000-000000000003'),'bags consume no rice');
INSERT INTO order_items(id,order_id,product_id,quantity,is_subscription) VALUES('30000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001',1,true);
SELECT test_assert((SELECT count(*)=0 FROM kg_item_snapshots WHERE item_id='30000000-0000-0000-0000-000000000004'),'subscription requires review');
SET test.uid='00000000-0000-0000-0000-000000000001';
SELECT kg_resolve_item('30000000-0000-0000-0000-000000000001','[{"season_id":"40000000-0000-0000-0000-000000000001","variety_key":"koshihikari","unit_kg":5}]',false,'checked legacy invoice');
SELECT test_assert((SELECT sum(used_kg)=10 FROM kg_movements WHERE item_id='30000000-0000-0000-0000-000000000001'),'explicit legacy resolution');
SELECT kg_record_movement('50000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','koshihikari','receipt',12.125,'harvest');
SELECT kg_record_movement('50000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','koshihikari','receipt',12.125,'retry');
SELECT test_assert((SELECT sum(incoming_kg)=12.125 FROM kg_movements),'manual retry idempotent');
UPDATE order_items SET quantity=4 WHERE id='30000000-0000-0000-0000-000000000002';
SELECT test_assert((SELECT reason LIKE 'REVIEW:%' FROM kg_item_snapshots WHERE item_id='30000000-0000-0000-0000-000000000002'),'changed item review');
SET ROLE authenticated;
SET test.uid='00000000-0000-0000-0000-000000000002';
SELECT test_assert((SELECT count(*)=0 FROM kg_movements),'non-admin cannot read');
DO $$ BEGIN
 BEGIN PERFORM kg_record_movement(gen_random_uuid(),'40000000-0000-0000-0000-000000000001','koshihikari','receipt',1,'forbidden'); RAISE EXCEPTION 'FAIL authorization';
 EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'admin required' THEN RAISE; END IF; END;
END $$;
RESET ROLE;
SELECT test_assert(NOT has_function_privilege('anon','kg_sync_item(uuid)','execute'),'anon has no internal RPC');
SELECT 'kg integration tests passed' AS result;
SET test.uid='00000000-0000-0000-0000-000000000001';
INSERT INTO inventory_varieties(season_id,variety_key,harvested_kg,reserved_kg) VALUES('40000000-0000-0000-0000-000000000001','koshihikari',100,20);
SELECT kg_review_legacy('40000000-0000-0000-0000-000000000001','koshihikari',5,'15kg matched to EC, 5kg external');
SELECT kg_review_legacy('40000000-0000-0000-0000-000000000001','koshihikari',5,'retry same values');
SELECT test_assert((SELECT sum(held_kg)=5 FROM kg_movements WHERE kind='legacy_review'),'legacy review does not double reserve');
SELECT test_assert((SELECT reserved_kg=20 FROM inventory_varieties),'legacy reservation retained');
SELECT kg_review_legacy('40000000-0000-0000-0000-000000000001','koshihikari',0,'external hold released');
SELECT test_assert((SELECT sum(held_kg)=0 FROM kg_movements WHERE kind='legacy_review'),'external legacy hold released');
SELECT test_assert((SELECT jsonb_array_length(kg_report()->'orders')=2),'report includes all orders');
SELECT 'all kg tests including legacy review passed' AS result;
-- Supabase's existing table grants are represented explicitly in the local fixture.
GRANT SELECT ON products,orders,order_items,inventory_seasons,inventory_varieties,inventory_external_sales TO authenticated;
SET ROLE authenticated;
SET test.uid='00000000-0000-0000-0000-000000000001';
SELECT test_assert(kg_report() IS NOT NULL,'existing admin can use invoker report');
UPDATE kg_product_specs SET note='admin verified' WHERE excluded;
SET test.uid='00000000-0000-0000-0000-000000000002';
SELECT test_assert(kg_report() IS NULL,'non-admin report returns no data');
RESET ROLE;
DO $$ BEGIN
 BEGIN PERFORM kg_validate_components('[{"season_id":"40000000-0000-0000-0000-000000000001","variety_key":"koshihikari","unit_kg":0.0001}]',false); RAISE EXCEPTION 'FAIL validation';
 EXCEPTION WHEN raise_exception THEN IF SQLERRM='FAIL validation' THEN RAISE; END IF; END;
END $$;
SELECT 'final kg DB assertions passed' AS result;
